assert len(CH) == 40
os.makedirs(os.path.join(OUT, "chapters"), exist_ok=True)
seen = set(); total = 0; meta_ch = []
for cid, num, unit, title, qs in CH:
    assert len(qs) == 8, (num, len(qs))
    rng = random.Random("st-istoria-" + cid)
    out = []
    for question, right, *wrong in qs:
        assert len(wrong) == 3 and len({right, *wrong}) == 4, question
        assert question not in seen, question
        seen.add(question)
        choices = [right] + wrong
        rng.shuffle(choices)
        out.append({"question": question, "choices": [f"{i+1}. {c}" for i, c in enumerate(choices)], "answer": str(choices.index(right) + 1)})
    total += len(out)
    with open(os.path.join(OUT, "chapters", f"{cid}.json"), "w", encoding="utf8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2); f.write("\n")
    meta_ch.append({"id": cid, "num": num, "title": title, "unit": unit})
with open(os.path.join(OUT, "meta.json"), "w", encoding="utf8") as f:
    json.dump({"grade": "ΣΤ΄ Δημοτικού", "source": "Ιστορία ΣΤ΄ Δημοτικού — Νεότεροι χρόνοι και σύγχρονη εποχή (Βιβλίο Μαθητή): " + SOURCE, "chapters": meta_ch}, f, ensure_ascii=False, indent=2); f.write("\n")
print(f"{len(CH)} κεφάλαια, {total} ερωτήσεις")
